@startuml

class User {
  + ID : string
  + Name : string
  + Email : string
  + DateOfBirth : date
}

class Account {
  + AccountNumber : long
}

class BusinessAccount extends Account {
  + CompanyName : string
  + MonthlyFee : float
}

class PersonalAccount extends Account {
}

class Page {
  + PageName : string
  + NumberOfVisits : int
}

class AdvertisementPage extends Page {
  + BounceRate : float
  + ClickThroughRate : float
  + ConversionRate : float
}

User "1" -- "0..1" Account
Account "1" -- "0..*" Page

PersonalAccount "0..1" -- "0..*" Page : privileges
PersonalAccount "1" -- "0..*" PersonalAccount : friend request

@enduml

